using System.Text.RegularExpressions;
using SnipeIt.Automation.Tests.Models.Enums;

namespace SnipeIt.Automation.Tests.Models;

public class AssetData
{
    // Input data (generated by the builder)
    public string Company { get; set; } = string.Empty;
    public string Name { get; init; } = string.Empty;
    public string Serial { get; init; } = string.Empty;
    public string ModelSearchText { get; init; } = string.Empty;
    public AssetStatus Status { get; init; }

    // Data read back from the form when creating the asset
    public string AssetTag { get; set; } = string.Empty;
    public string ModelDisplayText { get; set; } = string.Empty;  // Laptops - Macbook Pro 13" (#5219...)
    public string CheckedOutTo { get; set; } = string.Empty;      // Rhiannon Abbott (ward.hadley) - #10903

    private static readonly Regex ModelRegex = new(
        @"^(?<category>.+?)\s-\s(?<name>.+?)(?:\s\(#(?<number>[^)]*)\))?$",
        RegexOptions.Compiled);

    private Match ModelMatch => ModelRegex.Match(ModelDisplayText.Trim());

    public string Category => ModelMatch.Groups["category"].Value;
    public string ModelName => ModelMatch.Groups["name"].Value;     // Macbook Pro 13"
    public string ModelNumber => ModelMatch.Groups["number"].Value; // May be empty.

    // Keep only the name, removing "(username)" or "- #id" for comparison with the list/details page.
    public string CheckedOutToName =>
        Regex.Replace(CheckedOutTo, @"\s*(\(.*|-\s*#\d+.*)$", "").Trim();
}